(function(root){'use strict';
function schedule(result){if(!result?.plan||!['CONSENSUS','FALLBACK'].includes(result.status))return [];return [...result.plan.events].sort((a,b)=>a.landing-b.landing||a.flight.localeCompare(b.flight));}
function playback(result,cursor){const events=schedule(result),negotiation=result?.log?.length||0,total=negotiation+(events.length?events.length+1:0);return {events,negotiation,total,agreed:negotiation>0&&cursor>=negotiation,confirmed:Math.min(events.length,Math.max(0,cursor-negotiation)),finished:total>0&&cursor>=total};}
function groups(events,size=5){const out=[];for(let i=0;i<events.length;i+=size)out.push(events.slice(i,i+size));return out;}
function carrier(f){return f.carrier||f.historical?.airline||f.callsign?.match(/^[A-Z]+/)?.[0]||'Unspecified';}

const remedies={CREW_FLIGHT_TIME:'Review the affected crew’s remaining flying budget or plan a crew change. Do not increase a legal budget just to get agreement.',CREW_DUTY:'Review crew availability and the next flight timing, or model a crew change.',CREW_CAPACITY:'Add an actually available ground team or spread turnarounds over time.',GATE_BUFFER:'Free another compatible stand or delay its next occupant; preserve the gate buffer.',STAND_AVAILABLE:'Review gate release and equipment-ready times.',FUEL_RESERVE:'Reduce holding with an earlier feasible slot, or assess a reachable alternate. Preserve the protected reserve.',ALTERNATE_FUEL:'Review the required alternate, available fuel and holding time.',RUNWAY_AVAILABLE:'Choose an open runway or a slot after reopening.',TAXIWAY_BLOCKED:'Choose a route with no blocked segment.',WEATHER_AVOIDANCE:'Review the assessed route and storm clearance; do not reduce the weather margin.',WEATHER_WINDOW:'Choose a slot outside the weather closure.',WAKE_SEPARATION:'Increase arrival spacing to the required wake minimum.',RADAR_SEPARATION:'Increase arrival spacing to the radar minimum.',MIN_TURNAROUND:'Allow the configured minimum turnaround before the next departure.'};
function readableEvidence(c){if(c.code==='CREW_FLIGHT_TIME'){const m=c.evidence.match(/next flight (\d+(?:\.\d+)?) min.*budget (\d+(?:\.\d+)?)/);if(m)return 'Required flying time '+m[1]+' min exceeds the remaining '+m[2]+' min budget by '+(Number(m[1])-Number(m[2])).toFixed(1)+' min.';}return c.evidence;}
function blockers(result){if(!result||result.plan)return [];if(result.status==='NOT_EVALUATED'){const missing=result.missing||result.log?.find(m=>m.missing)?.missing||[];return missing.map(path=>({domain:'validator',label:path.startsWith('AI backend')?'AI backend unavailable':'Missing or invalid input: '+path,evidence:path.startsWith('AI backend')?path:'This required input could not be validated.',remedy:path.startsWith('AI backend')?'Configure the local server and its environment credential, then rerun. Do not change flight safety inputs.':'Supply and assess this input before rerunning.'}));}const failed=result.diagnostics?.failures||[];if(failed.length)return failed.map(c=>({...c,evidence:readableEvidence(c),remedy:remedies[c.code]||'Review the operational evidence and provide a feasible alternative; keep every hard margin intact.'}));const last=[...(result.log||[])].reverse().find(m=>m.type==='PROPOSE');return (result.log||[]).filter(m=>m.proposal_id===last?.proposal?.id).flatMap(m=>(m.checks||[]).filter(c=>!c.pass).map(c=>({...c,domain:m.sender,remedy:remedies[c.code]||'Review this constraint and its operational inputs.'})));}

root.RecoveryPresentation={blockers,schedule,playback,groups,carrier};if(typeof module!=='undefined')module.exports=root.RecoveryPresentation;
})(typeof window!=='undefined'?window:globalThis);
